import{_ as e,o,c as i,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Keynote: Welcome & Opening Remarks","description":"","frontmatter":{"title":"Keynote: Welcome & Opening Remarks","date":"2023-05-05T00:00:00.000Z","updated":"2023-05-05T00:00:00.000Z","tags":["Ceph","会议","开发者","分布式存储","Ceph 社区"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Keynote_-_Welcome_Opening_Remarks.md","filePath":"posts/2023/Keynote_-_Welcome_Opening_Remarks.md","lastUpdated":1780459816000}'),t={name:"posts/2023/Keynote_-_Welcome_Opening_Remarks.md"};function p(s,l,r,a,g,_){return o(),i("div",null,[...l[0]||(l[0]=[n('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题：</strong> Cephalocon 会议开幕</p><p><strong>会议时间：</strong> 具体日期未提供</p><p><strong>会议地点：</strong> 未明确指出</p><p><strong>主持人：</strong> Dan 和 Josh</p><p><strong>参会人员：</strong> Cephalocon 参会者、Ceph 社区成员、赞助商代表（包括 Bloomberg、IBM、42on、Canonical、Clyso 和 Core）</p><p><strong>会议内容摘要：</strong></p><ol><li><p><strong>开场致辞：</strong></p><ul><li>Dan 和 Josh 欢迎大家参加自2019年巴塞罗那以来的首次线下 Cephalocon 会议。</li><li>回顾了 Ceph 过去四年的发展，包括发布了五个新版本（Nautilus, Octopus, Pacific, Quincy, Reef）。</li><li>指出领导层变动，Josh 和 Dan 代表 Ceph 执行委员会。</li></ul></li><li><p><strong>会议组织情况：</strong></p><ul><li>会议门票已售罄，感谢所有参会者的支持。</li><li>强调 Linux 基金会活动的共同规则，确保参会者感到受欢迎和包容。</li><li>介绍会议日程，包括每天上午的主题演讲和全天三个并行会议。</li></ul></li><li><p><strong>会议设施与活动：</strong></p><ul><li>提供全天茶歇和午餐服务。</li><li>分享昨天开发者峰会的内容，并强调赞助商展示和今晚的展位巡游活动。</li></ul></li><li><p><strong>感谢与支持：</strong></p><ul><li>感谢 Ceph 基金会成员、赞助商、演讲者和整个 Ceph 社区的支持。</li><li>特别感谢铂金赞助商 Bloomberg 和 IBM，以及银级赞助商 42on、Canonical 和 Clyso。</li></ul></li><li><p><strong>Ceph 基金会介绍：</strong></p><ul><li>基金会成立于2018年，致力于全球范围内组织和推动 Ceph 的发展。</li><li>负责组织 Ceph 日和 Cephalocon 等活动，讨论项目方向，提升社区的可靠性和测试硬件。</li></ul></li><li><p><strong>未来活动预告：</strong></p><ul><li>计划在印度、温哥华和首尔举办更多 Ceph 相关活动。</li><li>鼓励各地组织 Ceph 日活动，并提供了联系基金会的方式。</li></ul></li><li><p><strong>会议后续安排：</strong></p><ul><li>接下来的议程包括 IBM 的“存储的未来”演讲和开发者对当前 Ceph 项目状态的更新。</li></ul></li></ol><p><strong>后续行动计划：</strong></p><ul><li>参会者应关注会议日程，积极参与各项活动。</li><li>对有兴趣组织 Ceph 日活动者，可联系基金会获取更多信息。</li><li>继续支持 Ceph 社区和基金会的工作，共同推动项目发展。</li></ul><p><strong>备注：</strong></p><ul><li>请参会者注意会议期间的各项安排和规则，确保会议顺利进行。</li><li>对于 Ceph 项目的具体技术更新和未来发展方向，将在后续会议中详细讨论。</li></ul>',12)])])}const h=e(t,[["render",p]]);export{u as __pageData,h as default};
